_e("LB-4", "LB-01", "ESTIMATE", "caveat", "The top Yukawa at the b–tau scale is 0.70, about 73 times the jet bound: in backgrounds of this class the third family cannot be a jet; y_b (0.0104) sits at the bound.", "mtft.matter.lattice_breaking", "test_lb01_lattice_breaking.py", "CC-46: closes degree-2 jets; a constant-jet top at its own point is marginal, not excluded")
_e("TF-1", "TF-01", "EXACT", "active", "Any quark Yukawa between jet families needs at least |e_Q| + 1 >= 2 units of rotation breaking, because the condensate shares u^c's block and its density reaches character -(|e_u| - 1) at best.", "mtft.matter.top_family", "test_tf01_top_family.py")
_e("TF-2", "TF-01", "NUMERICAL", "caveat", "143a1's two-fold anisotropy E2-hat = 0.105 gives two-unit breaking 0.019-0.075 at the blow-up scale: even a degree-0 jet top is nine times short of y_t = 0.70.", "mtft.matter.top_family", "test_tf01_top_family.py", "CC-46: the two units can be paid by the condensate's global component at (r/L)^2-(2r/L)^2 = 0.11-0.70, not only by the lattice anisotropy")
_e("TF-3", "TF-01", "STRUCTURAL", "retracted", "Two-plus-one design: two degree-1 jet families (|e| = 2) and one flux family with a b = 1 ((1,1) on Q, (-1,-1) on u^c), torus-constant Phi-type Higgs, global tree-level Yukawa; jets need 3 units.", "mtft.matter.top_family", "test_tf01_top_family.py", "CC-45: torus flux gives 24 chiral families per unit (chi(V*) - chi(V) = 24 b)")
_e("TP-1", "TP-01", "EXACT", "active", "chi(V*) - chi(V) = 24 b: one unit of torus flux gives 2g - 2 = 24 chiral families (one A-type, 23 Phi-type); chiral families come only from exceptional charges.", "mtft.matter.top_point", "test_tp01_top_point.py")
_e("TP-2", "TP-01", "ESTIMATE", "active", "A constant-jet top's two units can be paid by the global condensate's second Taylor coefficient at (r/L)^2 to (2r/L)^2: 0.11-0.42 at eps = A_E/3, up to 0.70 at 0.55 A_E — marginal, not excluded.", "mtft.matter.top_point", "test_tp01_top_point.py")
_e("TP-3", "TP-01", "STRUCTURAL", "caveat", "Two-point design: (cusp, O) with exceptional charge 2 gives two degree-1 jet families, (cusp, P) with charge 1 gives the constant-jet top; the coupling Higgs ((+4, +2)) stays a torus-constant Phi-type pullback.", "mtft.matter.top_point", "test_tp01_top_point.py", "TA-3: on one cusp fibre the top blow-up cannot be separated from the jets; the top point must move to another curve fibre")
_e("TP-4", "TP-01", "EXACT", "caveat", "The Phi-type Higgs space is H^0(C, K_C (x) L_H), deg 24 - (a_Q + a_u): thirteen cusp forms at 0, exactly one (curve-constant) when a_Q + a_u = 24 and L_Q (x) L_u = K_C.", "mtft.matter.top_point", "test_tp01_top_point.py", "CC-49: a D-flat Q block is unstable once the condensate forms; the relation becomes the inequality xi_4L >= (11/13) xi_R4")
_e("CC-45", "correction", "EXACT", "active", "Retracts TF-3: a flux family is 24 families; the toolkit's index sum e - 24 b already said so.", "mtft.matter.top_point", "test_tp01_top_point.py")
_e("CC-46", "correction", "EXACT", "active", "Caveats TF-2 and LB-4: the global condensate component can pay two units of character at (r/L)^2-(2r/L)^2, so the constant-jet top is marginal rather than excluded.", "mtft.matter.top_point", "test_tp01_top_point.py")
_e("TA-1", "TA-01", "NUMERICAL", "active", "On the unit-area torus of 143a1 the deep hole is 0.626 from O; the farthest torsion points (3-torsion) are at 0.598, the 2-torsion points at 0.494 and 0.563.", "mtft.matter.two_point_audit", "test_ta01_two_point_audit.py")
_e("TA-2", "TA-01", "EXACT", "active", "Two-point constraints: D-flatness 2 eps1 + eps2 = a_Q A_E and, on a shared fibre, eps1 + eps2 < A_E; the top needs eps2 ~ 0.55 A_E (radius 0.418), eps1 = 0.225 for a_Q = 1.", "mtft.matter.two_point_audit", "test_ta01_two_point_audit.py")
_e("TA-3", "TA-01", "ESTIMATE", "active", "Jet tails fall like (r/d)^(3+k): at the best separation 0.598 the top's tail at the jets is 0.16-0.34, so V_cb ~ 0.16-0.34 against 0.041 — the same-fibre design fails by 4-8x.", "mtft.matter.two_point_audit", "test_ta01_two_point_audit.py")
_e("TA-4", "TA-01", "STRUCTURAL", "active", "V_cb = 0.041 needs a separation of ~2.9 top-radii (0.95-1.21), beyond the fibre: the top's point must sit on another curve fibre, at a non-cusp point (another cusp is too far, CC-37).", "mtft.matter.two_point_audit", "test_ta01_two_point_audit.py")
_e("SP-1", "SP-01", "NUMERICAL", "active", "Canonical-metric (area 1) path lengths from the blown-up cusp: 0.178 to the points over tau/2 and (1+tau)/2, 0.189 over 1/2, 0.107 to i/sqrt(143), 0.214 to the opposite cusp.", "mtft.matter.special_points", "test_sp01_special_points.py")
_e("SP-2", "SP-01", "ESTIMATE", "caveat", "V_cb = 0.041 fixes the curve's area: A_X ~ 18 A_E (top blow-up A_E/3) to 34-36 A_E (0.55 A_E) for a top over a 2-torsion point, 19-32 A_E for a top at another cusp.", "mtft.matter.special_points", "test_sp01_special_points.py", "CC-50: V_cb is a difference of up and down rotations, fixed by mass ratios when the second family is induced; it does not measure r")
_e("SP-3", "SP-01", "STRUCTURAL", "active", "In the canonical metric the other cusps sit only slightly farther than the 2-torsion points; at A_X ~ 18 A_E their mixing is 0.034-0.046, not <= 1/143.", "mtft.matter.special_points", "test_sp01_special_points.py")
_e("SP-4", "SP-01", "STRUCTURAL", "active", "The top's candidate homes are the points over E's 2-torsion (where gamma-charged fermions localise, NU-01) or the Atkin–Lehner images of the jets' cusp.", "mtft.matter.special_points", "test_sp01_special_points.py")
_e("CC-47", "correction", "EXACT", "active", "Caveats CK1-1 and CC-37: their 1/143 bound used the hyperbolic metric with exponential decay, not the smooth physical metric at the blown-up cusp.", "mtft.matter.special_points", "test_sp01_special_points.py")
_e("GC-1", "GC-01", "EXACT", "active", "With no torus flux A_X enters every gauge coupling only through the volume A_X A_E - sum eps^2/2: coupling ratios fix V/kappa, never the shape A_X/A_E.", "mtft.matter.gauge_couplings", "test_gc01_gauge_couplings.py")
_e("GC-2", "GC-01", "NUMERICAL", "active", "SM one loop: R = (a_R^-1 - a_4^-1)/(a_L^-1 - a_4^-1) is 3.99 at m_Z, 3.678 at the b-tau crossing, 1 at 5.1e13 GeV (g_L = g_R); alpha_2 = alpha_3 at 9.7e16 GeV.", "mtft.matter.gauge_couplings", "test_gc01_gauge_couplings.py")
_e("GC-3", "GC-01", "EXACT", "active", "Flux-only splitting quantises R: two-point designs give 1/9, 3/7, 1, 7/3, 9 and the single-point design 1/5, 1, 5; none reaches 3.678.", "mtft.matter.gauge_couplings", "test_gc01_gauge_couplings.py", "assumes Re f = J^2/2 - kappa F^2/2 with universal kappa")
_e("GC-4", "GC-01", "ESTIMATE", "active", "The allowed matching scales are 8.9e11-2.1e14 GeV, 6-8 orders above the b-tau crossing, where y_b/y_tau = 0.66-0.71: b-tau would need a 30-35 per cent correction.", "mtft.matter.gauge_couplings", "test_gc01_gauge_couplings.py")
_e("GC-5", "GC-01", "EXACT", "active", "P1 = (cusp, O) is fixed by the torus involution, so the top point's torus coordinate is critical at the four 2-torsion points; no automorphism fixes a cusp, so the curve coordinate is unselected.", "mtft.matter.gauge_couplings", "test_gc01_gauge_couplings.py")
_e("CC-48", "correction", "EXACT", "active", "Caveats PS1-4 as the Pati–Salam scale: gauge matching with flux-split couplings allows only 8.9e11-2.1e14 GeV; results evaluated at 1.1e6 GeV inherit the caveat.", "mtft.matter.gauge_couplings", "test_gc01_gauge_couplings.py")
_e("TH-1", "TH-01", "EXACT", "active", "A vector-like (4,2,1) pair shifts (N, D) by (+4/3, -4/3)/(2 pi) per log, a (4bar,1,2) pair by the opposite: equal left and right pairs leave the matching ratio unchanged.", "mtft.matter.thresholds", "test_th01_thresholds.py")
_e("TH-2", "TH-01", "NUMERICAL", "active", "Reaching R = 7/3 at the b-tau scale needs n l = 29.2 light right-handed pairs times log (R = 1: 96.9); 19 pairs a factor 4.7 below; colour adjoints alone need Delta b_3 l = 195.", "mtft.matter.thresholds", "test_th01_thresholds.py")
_e("TH-3", "TH-01", "EXACT", "caveat", "The gamma-neutral two-point design has one vector-like pair per block; gamma-charged matter with c_L = c_R = c (bidoublet still neutral) adds 4c^2: 17 per block at c = 2.", "mtft.matter.thresholds", "test_th01_thresholds.py", "VM-2: the pairs are massless at tree level; the reconciliation needs a mass source the model does not yet have")
_e("TH-4", "TH-01", "STRUCTURAL", "active", "The shape A_X/A_E enters the matching only through the Kaluza–Klein towers: the torus's DKL factor (Im tau |eta|^4 = 0.3527 for 143a1) against the curve's spectral invariant.", "mtft.matter.thresholds", "test_th01_thresholds.py")
_e("VM-1", "VM-01", "EXACT", "active", "The Pati–Salam condensate gives vector-like pairs no holomorphic mass at any order: Sigma psi psi' is not SU(4)-invariant, Sigma-bar = 0, and Sigma^4 vanishes for a rank-one condensate.", "mtft.matter.vector_like_masses", "test_vm01_vector_like_masses.py")
_e("VM-2", "VM-01", "EXACT", "active", "Nothing else in the vacuum lifts them at tree level: adjoint bosons have positive one-loop masses (no vev) and torus Wilson lines only move the gamma-localised pairs.", "mtft.matter.vector_like_masses", "test_vm01_vector_like_masses.py")
_e("VM-3", "VM-01", "STRUCTURAL", "active", "Massless coloured vector-like states are excluded, so the gamma-charged-matter design needs a mass source anyway; that source decides the left-right asymmetry TH-01 needs.", "mtft.matter.vector_like_masses", "test_vm01_vector_like_masses.py")
_e("VM-4", "VM-01", "ESTIMATE", "superseded", "A conjugate condensate would give m ~ v_R^2/M_* to both sides; m_R ~ M_PS/5.6 then needs the cutoff or Kaluza–Klein scale within a factor ~6 of the Pati–Salam scale.", "mtft.matter.vector_like_masses", "test_vm01_vector_like_masses.py", "CO-1: the D-term vacuum has one orientation as a theorem of the field content")
_e("CO-1", "CO-01", "EXACT", "active", "Rank-one D-term vacuum: v^2 = (8/13) xi, residual U(1) D = -(5/13) xi; an aligned conjugate enters only through v^2 - vbar^2, any positive mass lifts the family to vbar = 0: no conjugate condensate in this field content.", "mtft.matter.conjugate_orientation", "test_co01_conjugate_orientation.py")
_e("CO-2", "CO-01", "NUMERICAL", "active", "Radiative Dirac masses from gauge loops give m_R/m_L = 0.90 at the b-tau scale (Casimirs 15/8, 3/4): ten per cent, not the factor five TH-01 needs.", "mtft.matter.conjugate_orientation", "test_co01_conjugate_orientation.py")
_e("CO-3", "CO-01", "EXACT", "active", "In the condensate's block the other scalars sit in the residual D-terms: m^2 = (10/13) g^2 xi (e^c-type) and (2/13) g^2 xi (coloured) — Pati–Salam-scale — while the left-handed block feels no SU(2)_R D-term.", "mtft.matter.conjugate_orientation", "test_co01_conjugate_orientation.py")
_e("CO-4", "CO-01", "STRUCTURAL", "active", "Heavy right-handed scalar partners suppress the right-handed fermion pairs' radiative masses: the one mechanism in the field content with TH-01's direction; its size needs the one-loop computation.", "mtft.matter.conjugate_orientation", "test_co01_conjugate_orientation.py")
_e("VS-1", "VS-01", "EXACT", "active", "The condensate shifts D_4 by -v^2 and its SU(4) D-term by -v^2 (T^A)_44: squark doublets get m^2 = g^2[xi_4L - (7/8) v^2], the slepton doublet g^2[xi_4L - (11/8) v^2], v^2 = (8/13) xi_R4.", "mtft.matter.vacuum_stability", "test_vs01_vacuum_stability.py")
_e("VS-2", "VS-01", "EXACT", "active", "A D-flat Q block is tachyonic once the condensate forms (colour and the electroweak group would break at the Pati–Salam scale); stability needs xi_4L >= (11/13) xi_R4.", "mtft.matter.vacuum_stability", "test_vs01_vacuum_stability.py")
_e("VS-3", "VS-01", "STRUCTURAL", "active", "With exceptional terms entering both FIs alike, the unique-Higgs pair (a_Q, a_u) = (11, 13) is unstable and (13, 11) is stable: stability orders the curve degrees a_Q > a_u.", "mtft.matter.vacuum_stability", "test_vs01_vacuum_stability.py")
_e("VS-4", "VS-01", "ESTIMATE", "active", "Left-handed partners sit near the stability edge, right-handed ones at the Pati–Salam scale: m_R/m_L ~ (M_SS/M_PS)^2, so TH-01's factor five needs M_SS ~ M_PS/2, and the left-handed pairs become the lightest new states.", "mtft.matter.vacuum_stability", "test_vs01_vacuum_stability.py")
_e("CC-49", "correction", "EXACT", "active", "Caveats TP-4 and FS-1: D-flatness of the (4,L) block is not a viable criterion; the condensate's D-term feedback requires xi_4L >= (11/13) xi_R4.", "mtft.matter.vacuum_stability", "test_vs01_vacuum_stability.py")
_e("GS-1", "GS-01", "EXACT", "active", "With dynamical Kaehler moduli the D-term potential (xi - v^2)^2/2 + (5/16) v^4 is minimised at v = 0, xi = 0: the FI-driven condensate needs moduli stabilised at nonzero FI by something outside the D-term sector.", "mtft.matter.green_schwarz", "test_gs01_green_schwarz.py")
_e("GS-2", "GS-01", "EXACT", "active", "The condensate's SU(4) D-term cannot relax: it gives (4,2,1) scalars +(1/8) g^2 v^2 (colour) and -(3/8) g^2 v^2 (lepton direction); only a fixed-moduli U(1) FI on the Q block lifts the slepton doublet.", "mtft.matter.green_schwarz", "test_gs01_green_schwarz.py")
_e("GS-3", "GS-01", "STRUCTURAL", "active", "U(1)_V (Phi: -2, A-type: +1) leaves every zero-mode cubic and D-term invariant and forbids the Dirac mass A A'; the Kaluza–Klein pairing Phi_n A_n breaks it, so vector-like masses are KK-mediated.", "mtft.matter.green_schwarz", "test_gs01_green_schwarz.py")
_e("MS-1", "MS-01", "EXACT", "active", "One-loop Casimir energy with a torus-only twist: V_E = alpha/A_X + beta/A_X^2 (Einstein frame), alpha < 0 from the leading term, beta of sign -a_1 (the twisted sector's summed curvature coefficient).", "mtft.matter.moduli_casimir", "test_ms01_moduli_casimir.py")
_e("MS-2", "MS-01", "EXACT", "active", "A minimum in A_X exists iff a_1 < 0, at A_X/A_E = (2 pi/3)(|a_1|/N)(S1/S0); chi(X_0(143)) = -24 enters a_1.", "mtft.matter.moduli_casimir", "test_ms01_moduli_casimir.py")
_e("MS-3", "MS-01", "NUMERICAL", "active", "Odd-winding sums of 143a1: S1 = 2.107219 (P = 1/2) and 3.238510 (pair), reproducing Matter-05; S1/S0 = 1.326, 1.081; a scalar count would give A_X = 11.1 or 9.06 A_E.", "mtft.matter.moduli_casimir", "test_ms01_moduli_casimir.py")
_e("MS-4", "MS-01", "STRUCTURAL", "superseded", "A first count for the 8D vector multiplet gives a_1 = -chi/3 = +8: the wrong sign, no minimum; flux terms of the matter blocks enter at the same order, so the verdict waits on the full spectrum.", "mtft.matter.moduli_casimir", "test_ms01_moduli_casimir.py", "MS-5/MS-6: the full twisted spectrum confirms the sign")
_e("MS-5", "MS-02", "EXACT", "active", "Each block's fields form Dolbeault pairs on the curve: a_1(0,0) = chi/6 + d/2, a_1(0,1) = -chi/3 - d/2, sum -chi/6 — flux cancels; per block a_1/N = -chi/12 = +2 for any flux, twist or Wilson line.", "mtft.matter.moduli_casimir", "test_ms01_moduli_casimir.py")
_e("MS-6", "MS-02", "EXACT", "active", "The size-independent term follows c_1.[omega] = chi(C) A_E - sum eps < 0, so for genus >= 2 the one-loop Casimir energy has no minimum in A_X; the jet vacuum's curve collapses; blow-ups make it worse.", "mtft.matter.moduli_casimir", "test_ms01_moduli_casimir.py")
_e("MS-7", "MS-02", "STRUCTURAL", "active", "Nothing in the model stabilises the Kaehler moduli; the consistent reading is a fixed geometry, where GS-1's relaxation does not occur and A_X/A_E stays a parameter measured by V_cb.", "mtft.matter.moduli_casimir", "test_ms01_moduli_casimir.py")
_e("CS-1", "CS-01", "EXACT", "active", "Pre-registered test of canonical prescriptions for A_X/A_E against V_cb's window [18.1, 36.4]: pullback through phi and the Petersson norm give 4, canonical metrics give 1 — misses.", "mtft.matter.canonical_shape", "test_cs01_canonical_shape.py")
_e("CS-2", "CS-01", "NUMERICAL", "active", "Hyperbolic area 56 pi over the Neron lattice area 3.9709 gives 44.30, or 22.15 with the |omega ^ omega-bar| convention: the range straddles the window, not a hit by the pre-registered rule.", "mtft.matter.canonical_shape", "test_cs01_canonical_shape.py")
_e("CS-3", "CS-01", "STRUCTURAL", "active", "No canonical prescription survives; at chance 0.10 per family about one accidental hit was expected, and the genus-type counts 24-28 in the window are numerology without a derivation. The shape stays a parameter measured by V_cb.", "mtft.matter.canonical_shape", "test_cs01_canonical_shape.py")
_e("DD-1", "DD-01", "EXACT", "active", "The torus involution fixes the jet point and both of the top's homes: the top and the curve-direction jet are even, the torus-direction jet odd.", "mtft.matter.double_duty", "test_dd01_double_duty.py")
_e("DD-2", "DD-01", "EXACT", "active", "With the involution unbroken the odd family decouples in both sectors, so the CKM matrix has a decoupled row and column: excluded. The data require the involution broken.", "mtft.matter.double_duty", "test_dd01_double_duty.py")
_e("DD-3", "DD-01", "STRUCTURAL", "active", "Breaking eps_P with the odd family first gives V_us ~ eps_P, V_cb from the tail, V_ub ~ c eps_P V_cb; the data need eps_P ~ 0.225 and c = 0.40. The gamma-flux on matter blocks is odd and supplies eps_P.", "mtft.matter.double_duty", "test_dd01_double_duty.py")
_e("DD-4", "DD-01", "ESTIMATE", "caveat", "With the gradient coupling V_cb ~ 3 (r1/d)(r2/d)^3 the required separation is 0.95-1.09 and the curve's area over a 2-torsion point 18-28 A_E (SP-2 said 18-36).", "mtft.matter.double_duty", "test_dd01_double_duty.py", "CC-50: the separation-from-V_cb reading assumed the tail angle equals V_cb")
_e("CA-1", "CA-01", "ESTIMATE", "caveat", "With EPS-01's gamma-tilt as the parity breaking, V_us = 0.225 requires r = A_X/A_E = 91-896 for gamma-charge 1 (363-3585 for charge 2).", "mtft.matter.cabibbo", "test_ca01_cabibbo.py", "CC-58: as a block tilt the gamma tilt cancels in the CKM (TL-2); the r-window maps its size to V_us only to order of magnitude")
_e("CA-2", "CA-01", "STRUCTURAL", "superseded", "V_cb with the top over a 2-torsion point needs r = 18.6-27.8: the two measurements of r miss by a factor 3.3; EPS-01's tilt and NU-02's neutrino windows side with the larger r.", "mtft.matter.cabibbo", "test_ca01_cabibbo.py", "CC-55: the gap came from single-image tails; with image sums V_cb's r overlaps CA-1 (FA-2)")
_e("CA-3", "CA-01", "MODEL", "superseded", "Post hoc: the top at the Fricke fixed point i/sqrt(143) (0.107 from the cusp, involution-fixed with torus point O) gives V_cb = 0.041 at r = 79-105, overlapping the Cabibbo window's lower edge.", "mtft.matter.cabibbo", "test_ca01_cabibbo.py", "CC-50: the Fricke candidate was chosen to fit r from V_cb, a premise TO-01 removes")
_e("CA-4", "CA-01", "STRUCTURAL", "active", "The data's V_ub coefficient c = 0.40 lies between the parity texture's down-sector value (about 1) and the up-sector GST value 0.20: consistent, not sharp.", "mtft.matter.cabibbo", "test_ca01_cabibbo.py")
_e("CA-5", "CA-01", "ESTIMATE", "active", "Gamma-charge 1 gives 5 vector-like pairs per block; TH-01's requirement then puts the right-handed pairs near 3 TeV, within collider reach.", "mtft.matter.cabibbo", "test_ca01_cabibbo.py")
_e("TO-1", "TO-01", "EXACT", "active", "In the two-point design the second family's direct entry costs three curve-direction units, at most 2.4e-4 (r = 18.6): its mass is induced by the third family's tail, m2/m3 = theta_L theta_R.", "mtft.matter.third_observable", "test_to01_third_observable.py")
_e("TO-2", "TO-01", "NUMERICAL", "active", "Pre-registered test: with left–right symmetric tails V_cb = |sqrt(m_s/m_b) - e^(i phi) sqrt(m_c/m_t)| lies in 0.078-0.199 for every phase, outside the window 0.030-0.055: fail, wherever the top sits.", "mtft.matter.third_observable", "test_to01_third_observable.py")
_e("TO-3", "TO-01", "STRUCTURAL", "active", "A geometric angle common to both sectors cancels in the CKM matrix, so V_cb does not measure the curve's size; the design needs left–right asymmetric tails, theta_R/theta_L ~ 7.7 in the down sector.", "mtft.matter.third_observable", "test_to01_third_observable.py")
_e("CC-50", "correction", "EXACT", "active", "Caveats SP-2, DD-4 and CA-2 and supersedes CA-3: they read V_cb as the top's tail angle, but the CKM element is a difference of up and down rotations fixed by mass ratios here.", "mtft.matter.third_observable", "test_to01_third_observable.py")
_e("FL-1", "FL-01", "EXACT", "active", "Off-diagonal entries are dominated by the degree-0 field's tail at the jet point: theta_L (the CKM angle) is set by the right-handed block's tail, theta_R by the Q block's, shared by up and down.", "mtft.matter.flux_tails", "test_fl01_flux_tails.py")
_e("FL-2", "FL-01", "EXACT", "caveat", "With the induced texture the data demand tails T(Q) : T(d^c) : T(u^c) = 40 : 5.3 : 1 (aligned phases) to 86 : 5.3 : 1 (opposite): Q longest, u^c shortest.", "mtft.matter.flux_tails", "test_fl01_flux_tails.py", "CD-2: the condensate dresses u^c only, so theta_R is not shared by up and down; the required tails depend on the dressing z")
_e("FL-3", "FL-01", "ESTIMATE", "active", "Curve flux sets tail ranges by the magnetic length; for a curve-direction separation the ratio is independent of A_X and reaches at most 13.8 under a_Q + a_u = 24 — short of 40, and stability's a_Q > a_u points it the wrong way.", "mtft.matter.flux_tails", "test_fl01_flux_tails.py")
_e("FL-4", "FL-01", "STRUCTURAL", "superseded", "The condensate acts on the right-handed block only and its SU(2)_R D-term splits u^c from d^c: the one ingredient with the shape the data demand.", "mtft.matter.flux_tails", "test_fl01_flux_tails.py", "CD-1/CD-2: the u^c-not-d^c distinction is the condensate's gauge–fermion mixing, an exact selection rule")
_e("CC-51", "correction", "EXACT", "active", "Corrects TO-01 item 4: theta_L is set by the right-handed block's tail, so the asymmetry needs the Q tail longer, and VS-3's flux ordering points the wrong way.", "mtft.matter.flux_tails", "test_fl01_flux_tails.py")
_e("CD-1", "CD-01", "EXACT", "active", "One broken generator carries the condensate's nu^c direction to u^c, e^c and nu^c, never to d^c or Q: its gauge–fermion mixing dresses u^c, e^c, nu^c only.", "mtft.matter.condensate_dressing", "test_cd01_condensate_dressing.py")
_e("CD-2", "CD-01", "STRUCTURAL", "active", "The admixed gauginos have no Yukawa coupling, so the dressing multiplies each u^c family's entries by its weight Z_j: theta_L^u is untouched, m_c/m_t and theta_R^u pick up z = Z_2/Z_3.", "mtft.matter.condensate_dressing", "test_cd01_condensate_dressing.py")
_e("CD-3", "CD-01", "EXACT", "active", "Given the induced texture the data need z = (m_c/m_t)/((m_s/m_b) - V_cb theta_R): z = 1 reproduces FL-2; z = 0.25 makes the tails nearly symmetric (Q : d^c : u^c = 0.71 : 1 : 0.75) with Q shortest, as stability requires.", "mtft.matter.condensate_dressing", "test_cd01_condensate_dressing.py")
_e("CD-4", "CD-01", "STRUCTURAL", "retracted", "z < 1 needs the charm's u^c dressed more than the top's — the condensate's jets sit beside the second family; the same dressing acts on e^c but not d^c, the lepton-specific structure CP-4 needed.", "mtft.matter.condensate_dressing", "test_cd01_condensate_dressing.py", "CC-52: dressing lowers Yukawas, so it cannot give the lepton structure (QL-1); earlier caveat DP-4")
_e("DP-1", "DP-01", "EXACT", "active", "Gauge invariance pairs u^c with the conjugate leptoquark gaugino: the light state stays massless with weight Z = M/sqrt(M^2 + m^2); no seesaw mass.", "mtft.matter.dressing_profiles", "test_dp01_dressing_profiles.py")
_e("DP-2", "DP-01", "EXACT", "active", "The charm's u^c (x-jet at P1) mixes only through the condensate's x-jet component at P1, the top's through its value at P2: z_u compares those local amplitudes.", "mtft.matter.dressing_profiles", "test_dp01_dressing_profiles.py")
_e("DP-3", "DP-01", "ESTIMATE", "caveat", "z_u = 0.25 needs m_2/M = 3.9 (undressed top) to 4.9 (Z_3 = 0.8): a strong x-jet component at P1 and a gaugino tower near M_PS/2.", "mtft.matter.dressing_profiles", "test_dp01_dressing_profiles.py")
_e("DP-4", "DP-01", "EXACT", "caveat", "With PS-symmetric tails, (m_mu/m_tau)/(m_s/m_b) = z_e = 3.09; the same condensate and towers give z_e = z_u, so the up sector's 0.25 and the leptons' 3.09 conflict by a factor 12.", "mtft.matter.dressing_profiles", "test_dp01_dressing_profiles.py", "unless SU(2)_R-breaking flux splits the leptoquark and W_R towers and reverses the spatial pattern")
_e("GT-1", "GT-01", "EXACT", "active", "Both gaugino towers' lowest modes are curve zero modes times the lowest twisted torus mode: equal mass if twisted alike; the flux-free leptoquark tower is uniform in the canonical metric.", "mtft.matter.gaugino_towers", "test_gt01_gaugino_towers.py")
_e("GT-2", "GT-01", "NUMERICAL", "active", "With the SU(2)_R flux sitting at the blown-up cusp (L = O(2 cusp)) the W_R tower's share of the canonical density is 0.0024-0.055 at the jets and 0.72 over tau/2: it avoids the jets and reaches the top's homes.", "mtft.matter.gaugino_towers", "test_gt01_gaugino_towers.py")
_e("GT-3", "GT-01", "EXACT", "active", "A subspace's Bergman density never exceeds the full one: with equal masses and couplings z_e <= 1/Z_3^u, so z_e = 3.09 forces Z_3^u <= 0.32 and m_2^u/M = 12.3.", "mtft.matter.gaugino_towers", "test_gt01_gaugino_towers.py")
_e("GT-4", "GT-01", "STRUCTURAL", "caveat", "The reversal needs a lighter W_R tower, M_LQ/M_WR >= 3.9 (4.6 at the homes): e.g. different Z/2 Wilson lines on B and A2, breaking SU(2)_R at the compactification scale. Shape available, strength the obstacle.", "mtft.matter.gaugino_towers", "test_gt01_gaugino_towers.py")
_e("QL-1", "QL-01", "EXACT", "active", "Dressing only lowers Yukawas: with tree-level b-tau equality and d^c undressed, z_e = 3.09 by dressing forces y_tau/y_b <= 0.32 at matching against 1.40-1.53 from GC-01's running: factor >= 4.4 (>= 3.1 with b-tau unification). The dressing route to the lepton structure is closed.", "mtft.matter.quark_lepton_split", "test_ql01_quark_lepton_split.py")
_e("QL-2", "QL-01", "NUMERICAL", "active", "Lepton/quark Yukawa ratios per family at matching: f_3 = 1.40-1.53, f_2 = 4.33-4.72, f_1 = 0.42-0.45; relative to the third family (running-independent) 3.09 and 0.30: the Georgi-Jarlskog pattern within 3% and 10%.", "mtft.matter.quark_lepton_split", "test_ql01_quark_lepton_split.py")
_e("QL-3", "QL-01", "STRUCTURAL", "superseded", "The only SU(4)-breaking at the down-sector vertex is the condensate in the nu^c direction, acting on the lepton component alone: f_j = 1 + kappa_j with kappa = (-0.58, +3.3, +0.40). The two P1 families need opposite signs (insertion odd under jet parity); a condensate factor inside the Yukawa amplitude is the only candidate left.", "mtft.matter.quark_lepton_split", "test_ql01_quark_lepton_split.py", "CC-53: the requirement sits on entries, not families (one sign), and the condensate insertion cannot supply it (CI-2, CI-4)")
_e("QL-4", "QL-01", "ESTIMATE", "caveat", "The Wilson-line split hits the ratio in the massless-W_R-gaugino limit (z_e = 2.7-3.3 at r ~ 100) but every lepton weight vanishes there: excluded by QL-1.", "mtft.matter.quark_lepton_split", "test_ql01_quark_lepton_split.py")
_e("CC-52", "correction", "EXACT", "active", "Retracts CD-4 and caveats DP-3, DP-4 and GT-4: kinetic dressing cannot supply the lepton structure because it only lowers Yukawas while the data need y_tau/y_b = 1.40-1.53 at matching (QL-1).", "mtft.matter.quark_lepton_split", "test_ql01_quark_lepton_split.py")
_e("CI-1", "CI-01", "EXACT", "active", "The condensate's internal direction is fixed by its bundle, so Sigma Sigma^dagger = |Sigma|^2 P_lepton everywhere: an entry's lepton/quark ratio is 1 + rho w_ij, rho universal, w_ij the share of the quark entry carried by the condensate channel.", "mtft.matter.condensate_insertion", "test_ci01_condensate_insertion.py")
_e("CI-2", "CI-01", "EXACT", "active", "Tail-carried entries are SU(4)-universal (flux commutes with SU(4); dressing <= 1). With the 2-3 entries tail-carried (TO-01, FL-01) the muon's 3.09 forces y_tau/y_b <= 0.57 at matching against 1.40-1.53: factor >= 2.46 (1.76 with b-tau unification).", "mtft.matter.condensate_insertion", "test_ci01_condensate_insertion.py")
_e("CI-3", "CI-01", "NUMERICAL", "active", "Running-independent entry pattern: 2-3 entries x1.758 relative to the 3-3 entry, 1-2 entries x0.959 - lepton tails 1.76 times quark tails with local entries untouched, predicting f_1 f_2 = f_3^2 (data 0.919, within m_d/m_s's 8%).", "mtft.matter.condensate_insertion", "test_ci01_condensate_insertion.py")
_e("CI-4", "CI-01", "ESTIMATE", "active", "Gaussian jets, holomorphic 1-jet condensate, zero singlet coefficient: the condensate channel's 2-3 excess is bounded by the tail lever arm 2d/(n l_1); the data need 5.9-7.7 (none below f_3 = 1.043), the n = 3 tail gives 2.4-3.0.", "mtft.matter.condensate_insertion", "test_ci01_condensate_insertion.py")
_e("CI-5", "CI-01", "STRUCTURAL", "caveat", "The single condensate gives the lepton pattern neither by dressing (QL-01) nor by insertion; the pattern needs SU(4) breaking in the zero modes themselves (lepton tails 1.76x quark tails), e.g. a discrete Wilson line along B-L.", "mtft.matter.condensate_insertion", "test_ci01_condensate_insertion.py", "CC-54: its example, the B-L Wilson line, gives the lepton pattern or V_cb but not both and sits at a one-loop saddle (BL-2, BL-3)")
_e("CC-53", "correction", "EXACT", "active", "Supersedes QL-3: the lepton requirement sits on entries (one sign; 2-3 entries x1.758), not families, and the condensate insertion cannot supply it - tail-carried entries are universal (CI-2), the condensate channel's lever arm is too short (CI-4).", "mtft.matter.condensate_insertion", "test_ci01_condensate_insertion.py")
_e("BL-1", "BL-01", "EXACT", "active", "Over a 2-torsion point torus images pair at equal distance: a Z/2 character that is -1 on the doubled offset cancels every pair, so the quark 2-3 entries vanish; one character per 2-torsion point survives (R from 0.92 over 1/2, 0.79 over tau/2). Twisting leptons instead only shrinks their tails.", "mtft.matter.bl_wilson_line", "test_bl01_bl_wilson_line.py")
_e("BL-2", "BL-01", "NUMERICAL", "active", "The lepton factor 1.758 is reached at s_X = 0.716 (over 1/2) or 0.499 (over tau/2), where the twisted quark V_cb is 0.133 or 0.184 against [0.030, 0.055]; at V_cb = 0.055-0.030 the muon factor is 6.6-18 instead of 3.09. The Wilson line gives the lepton pattern or V_cb, never both.", "mtft.matter.bl_wilson_line", "test_bl01_bl_wilson_line.py")
_e("BL-3", "BL-01", "EXACT", "active", "At one loop with matched spectra, every Z/2 point whose character differs from the Scherk-Schwarz one lies above theta = 0 with a negative Hessian eigenvalue (all six pairings; |w|^-4, -6, -8); equal characters make the leptoquark gauginos massless.", "mtft.matter.bl_wilson_line", "test_bl01_bl_wilson_line.py")
_e("BL-4", "BL-01", "NUMERICAL", "active", "Over a 2-torsion point the untwisted tail is an image sum led by the equidistant pair: 3.1 (over 1/2) to 3.5 (over tau/2) times DD-01's single-image estimate at s_X = 0.85, moving the separation V_cb wants outward by about 1.3.", "mtft.matter.bl_wilson_line", "test_bl01_bl_wilson_line.py")
_e("BL-5", "BL-01", "STRUCTURAL", "active", "With dressing (QL-01), the condensate insertion (CI-01) and the B-L Wilson line (BL-01) closed, the lepton pattern has no mechanism in the current matter sector: recorded as an open failure beside TO-01's V_cb and GC-01's b-tau normalisation.", "mtft.matter.bl_wilson_line", "test_bl01_bl_wilson_line.py")
_e("CC-54", "correction", "EXACT", "active", "Caveats CI-5: its example mechanism, a B-L Wilson line on the colour stack, gives the lepton pattern or V_cb but not both (BL-2) and sits at a one-loop saddle (BL-3).", "mtft.matter.bl_wilson_line", "test_bl01_bl_wilson_line.py")
_e("FA-1", "FA-01", "STRUCTURAL", "active", "Flavour scoreboard: eight observables, six continuous parameters introduced to meet them, two pre-registered tests (CS-01 no hit, TO-01 failed); nothing has yet passed a test it was not tuned to.", "mtft.matter.flavour_audit", "test_fa01_flavour_audit.py")
_e("FA-2", "FA-01", "NUMERICAL", "caveat", "Image-summed tails raise V_cb's r by 2.5-3.4: 63-130 over the 2-torsion points (single image 22-34), 196-359 at the Fricke point; both overlap CA-1's 91-896, the opposite cusp (49-90) touches it. Post hoc, flat-curve approximation.", "mtft.matter.flavour_audit", "test_fa01_flavour_audit.py", "CC-56: refined by the curved kernel (AG-4): the tau/2 home falls to the window edge, the Fricke home stays inside")
_e("FA-3", "FA-01", "EXACT", "active", "Gauss-Bonnet on genus 13: a canonical path of length l spans l sqrt(48 pi) = 12.28 l mean curvature radii at every A_X (1.3 to the Fricke point, 2.2-2.3 to the 2-torsion preimages, 2.6 to the opposite cusp): flat-curve tails are uncontrolled; the right object is the Arakelov Green's function.", "mtft.matter.flavour_audit", "test_fa01_flavour_audit.py")
_e("FA-4", "FA-01", "EXACT", "active", "X0(143)(Q) is exactly the four cusps (Faltings: finitely many; Mazur-Kenku: no rational cyclic 143-isogeny; all cusps rational for squarefree N). P2's curve coordinate has been fitted; arithmetic placement removes that parameter.", "mtft.matter.flavour_audit", "test_fa01_flavour_audit.py")
_e("FA-5", "FA-01", "STRUCTURAL", "active", "Four failures are independent of the tail normalisation and survive: TO-01 (a ratio of tails), the lepton pattern (exact, CI-2 and BL-1), the b-tau normalisation and the Pati-Salam scale.", "mtft.matter.flavour_audit", "test_fa01_flavour_audit.py")
_e("CC-55", "correction", "EXACT", "active", "Supersedes CA-2: the factor-3.3 gap between the two measurements of r came from single-image tails; with image sums V_cb's r overlaps CA-1's window (FA-2). The separations of SP-2 and DD-4 move outward accordingly.", "mtft.matter.flavour_audit", "test_fa01_flavour_audit.py")
_e("AG-1", "AG-01", "EXACT", "active", "Green's functions for different volume forms differ by f(P) + f(Q) + C, so all mixed second derivatives coincide: d_P d_Q g = B - pi w^T Y^-1 w and d_P dbar_Q g = pi w^T Y^-1 conj(w). The tail kernel is a conformal invariant; the canonical metric enters only through sqrt(mu(P) mu(Q)).", "mtft.matter.arakelov_kernel", "test_ag01_arakelov_kernel.py")
_e("AG-2", "AG-01", "EXACT", "active", "The second-kind differential with a lone double pole at the cusp is eta(t)eta(11t)/(eta(13t)eta(143t)) times a weight-2 cusp form vanishing to order 5 at infinity and 7 at 1/13 (no weight-2 eta quotient works; poles-only-at-infinity functions start at order 60); residue zero to 3e-14.", "mtft.matter.arakelov_kernel", "test_ag01_arakelov_kernel.py")
_e("AG-3", "AG-01", "NUMERICAL", "active", "Ford-domain integration over the Atkin-Lehner quotient (area 14 pi to 3e-6, Im Omega to 8e-6) gives K = |d d g|/sqrt(mu mu) from the cusp: 74.55 (Fricke point), 22.87 (tau/2 preimage), 13.02 (cusp 0), 1.73 and 1.27 (cusps 1/11, 1/13), stable to 0.8%; 0.85, 0.73, 0.60 of the flat 1/l^2.", "mtft.matter.arakelov_kernel", "test_ag01_arakelov_kernel.py")
_e("AG-4", "AG-01", "NUMERICAL", "active", "Pre-registered test (FA-01): r from V_cb = 0.030-0.055 lands at 167-306 (central 224) for the Fricke point, inside the Cabibbo window 91-896: PASS. The tau/2 preimage gives 51-94 (edge only), cusp 0 29-53, cusps 1/11 and 1/13 3-7: FAIL. Of four arithmetic homes only the CM point passes.", "mtft.matter.arakelov_kernel", "test_ag01_arakelov_kernel.py")
_e("AG-5", "AG-01", "STRUCTURAL", "active", "One pass in four homes, at a point CA-3 had flagged post hoc: modest evidence by the look-elsewhere count. It fixes the top's home at the Fricke point and r near 170-300, consistent with V_us (CA-1) and NU-02.", "mtft.matter.arakelov_kernel", "test_ag01_arakelov_kernel.py")
_e("CC-56", "correction", "EXACT", "active", "Caveats FA-2: its flat-curve image sums are refined by the canonical kernel (AG-4); the tau/2 home drops to the Cabibbo window's edge (51-94) while the Fricke home stays inside (167-306).", "mtft.matter.arakelov_kernel", "test_ag01_arakelov_kernel.py")
_e("FH-1", "FH-01", "EXACT", "active", "143a1 has root number -1, rank 1, trivial torsion and W_143-eigenvalue +1, so phi(W tau) = phi(tau) and the involution pins no torus point: the Fricke point maps to 0.22215 omega_1, not a 2-torsion point. A home on the graph of phi sits there; CA-3 placed it over O.", "mtft.matter.fricke_home", "test_fh01_fricke_home.py")
_e("FH-2", "FH-01", "NUMERICAL", "active", "Torus-nonuniform tail components decay as exp(-2 pi |k| s), |k| = 0.989; at the Fricke separation 1.62-1.79 that is 1.5e-5 to 4.2e-5, so the top's torus position is invisible and DD-01's parity rule holds over O or over phi(i/sqrt 143).", "mtft.matter.fricke_home", "test_fh01_fricke_home.py")
_e("FH-3", "FH-01", "NUMERICAL", "active", "Four measurements of r meet at the Fricke home: V_cb 167-306, V_us 91-896, EPS-01's tilt 230-2300 and NU-02's first window 96-280 share r = 230-280 (with the tau/2 home V_cb's r was disjoint from EPS-01's). Broad windows: supportive, not decisive.", "mtft.matter.fricke_home", "test_fh01_fricke_home.py")
_e("FH-4", "FH-01", "STRUCTURAL", "superseded", "With a torus-uniform tail the w-family reaches the top only through its parity-induced x-component. Rotation-type breaking cancels the down-sector V_ub and gives |V_ub/V_cb| = theta_12^u: 0.045 for symmetric up-sector entries against 0.090 (factor 2), unless the up-sector 1-2 entries are asymmetric (ratio 4). V_ub tests the breaking, not the home.", "mtft.matter.fricke_home", "test_fh01_fricke_home.py", "CC-57: rotation-type breaking is the pure lever (c = 1, massless first family); the texture-zero relation belongs to the pure local arm (LV-1)")
_e("LV-1", "LV-01", "EXACT", "active", "Two arms at the jet point: lever u = Y13/Y23 (grip on the tail's height vs the x-family's grip on its slope) and local v = Y12/m2. With zeros at (1,1), (2,2) and equal chiralities: V_us = |u - v|, V_ub/V_cb = |u|, m_d/m_s = |v(2u - v)|, c = |u|/|u - v| (checked to ~10%). Pure lever: c = 1, m_d = 0; pure local: GST, c from the up sector = 0.20.", "mtft.matter.lever", "test_lv01_lever.py")
_e("LV-2", "LV-01", "NUMERICAL", "active", "Down sector alone, c = 0.40 needs opposite arms: u = 0.090, v = -0.135, giving m_d/m_s = 0.042 against 0.050.", "mtft.matter.lever", "test_lv01_lever.py")
_e("LV-3", "LV-01", "ESTIMATE", "active", "With a symmetric up-sector 1-2 angle and one phase, an exact fit of V_us, V_cb, V_ub, m_d/m_s, m_s/m_b with real arms predicts gamma = 17 or 141 deg against 65.7: real arms fail. A twist between the arms fits it (-130 deg, lever share 0.26; or -89 deg, 0.46); the right-angle branch mirrors the measured near-right alpha.", "mtft.matter.lever", "test_lv01_lever.py")
_e("LV-4", "LV-01", "STRUCTURAL", "active", "c and gamma are set by the condensate's jets at the jet point (first-order misalignment, mixed second-order component, their relative phase), not yet computed; the pre-registered window c in [0.35, 0.45] moves there, with gamma = 65.7 +- 3 deg as a second target.", "mtft.matter.lever", "test_lv01_lever.py")
_e("CC-57", "correction", "EXACT", "active", "Supersedes FH-4: rotation-type breaking is the pure lever (Y13 = eps Y23: c = 1, massless first family); the texture-zero relation |V_ub/V_cb| = theta_12^u belongs to the pure local arm. FH-4 had computed the first family's third component, not V_ub.", "mtft.matter.lever", "test_lv01_lever.py")
_e("TL-1", "TL-01", "EXACT", "active", "The gamma bundle restricts to the flat torus bundles N_{c phi(x)} (a Poincare-type pullback): its curvature mixes curve and torus (odd under w -> -w) and makes the x- and w-jets at the jet point non-orthogonal, so the physical jets are a rotated pair: rotation-type breaking, LV-01's pure lever.", "mtft.matter.tilt", "test_tl01_tilt.py")
_e("TL-2", "TL-01", "EXACT", "active", "Rotations of matter blocks cannot make the Cabibbo angle: the shared quark-doublet tilt cancels in U_u^dagger U_d, right-handed tilts drop out of Y Y^dagger, and with the parity-decoupled vertex V_us = V_ub = 0 (to 1e-17). The tilt must act inside the vertex and differ between up and down (EPS-01's split).", "mtft.matter.tilt", "test_tl01_tilt.py")
_e("TL-3", "TL-01", "EXACT", "active", "With sector-dependent aligned tilts V_us = |u_d - u_u| and V_ub = V_us |s23_d|, so c = V_ub/(V_us V_cb) = |s23_d|/V_cb: V_ub measures the down quarks' share of V_cb (leading order; exact diagonalisation agrees to 3%).", "mtft.matter.tilt", "test_tl01_tilt.py")
_e("TL-4", "TL-01", "NUMERICAL", "active", "FL-01's shared right-handed tail and CD-01's dressing give s23_u/s23_d = (m_c/m_t)/(z m_s/m_b) = 0.19/z and c >= 1/(1 + 0.19/z): at DP-01's z = 0.25, c >= 0.565, outside the pre-registered window [0.35, 0.45] (FAIL); the window needs z <= 0.157 with nearly opposite 2-3 phases.", "mtft.matter.tilt", "test_tl01_tilt.py")
_e("TL-5", "TL-01", "STRUCTURAL", "superseded", "c = 0.40 needs either LV-01's local arm (opposite arms with a twist) or stronger up-sector dressing (z <= 0.16); both need the condensate's SU(2)_R split at the jet point, the one computation every route now points to.", "mtft.matter.tilt", "test_tl01_tilt.py", "CC-59: the split is the stack pattern — the condensate never touches the down sector, so neither route is open as stated (DS-1, DS-5)")
_e("CC-58", "correction", "EXACT", "active", "Caveats CA-1: as a matter-block rotation the gamma tilt cancels in the CKM (TL-2), so its r-window maps the tilt's size to V_us only to order of magnitude; FH-3's concordance inherits that weaker V_us window.", "mtft.matter.tilt", "test_tl01_tilt.py")
_e("DS-1", "DS-01", "EXACT", "active", "The nu^c condensate's first-order D-term is felt by u^c, e^c, nu^c, L and H_u (the A1/A2 stacks) and by none of Q, d^c, H_d (CD-1's pattern): the down sector has no first-order parity breaking and the Cabibbo angle is an up-sector quantity.", "mtft.matter.down_parity", "test_ds01_down_parity.py")
_e("DS-2", "DS-01", "EXACT", "active", "Parity-symmetric down sector with (2,2) negligible: m_s/m_b = tan theta_L^d tan theta_R and V_ub = V_us sin theta_L^d, so c >= (m_s/m_b)/(V_cb tan theta_R) and |V_ub| >= V_us (m_s/m_b)/tan theta_R: for theta_R <= 45 deg, c >= 0.47 (0.42-0.52) and |V_ub| >= 0.0043 (0.0039-0.0048). The pre-registered window is missed at central inputs, grazed within uncertainties.", "mtft.matter.down_parity", "test_ds01_down_parity.py")
_e("DS-3", "DS-01", "NUMERICAL", "active", "Solving the structure with the data (c = 0.40, V_cb, m_s/m_b, m_c/m_t, gamma = 65.7): tan theta_R = 1.17 (49.5 deg), sin theta_L^u = 0.050, 2-3 phase 48 deg, z = 0.063.", "mtft.matter.down_parity", "test_ds01_down_parity.py")
_e("DS-4", "DS-01", "ESTIMATE", "active", "With FL-01's assignment tan theta_R = 1.17 needs T(Q)/T(d^c) = 71; curve flux reaches at most 13.8, capping c at >= 0.91 and |V_ub| at >= 0.0084, 2.3 times the measured value; a Q-block tail of order one would leave the left-handed top unlocalised.", "mtft.matter.down_parity", "test_ds01_down_parity.py")
_e("DS-5", "DS-01", "STRUCTURAL", "active", "A two-point design with a parity-symmetric down sector predicts V_ub too large by >= 2.3: it needs first-order parity breaking in the down sector, which the nu^c condensate cannot supply, or a different home for the left-handed top. The fifth open failure.", "mtft.matter.down_parity", "test_ds01_down_parity.py")
_e("CC-59", "correction", "EXACT", "active", "Supersedes TL-5: the SU(2)_R split is the stack pattern (DS-1) — the condensate never reaches Q, d^c or H_d — so the local-arm route needs a down-sector parity-odd source the condensate cannot give, and the dressing route runs into the V_ub floor (DS-2, DS-4).", "mtft.matter.down_parity", "test_ds01_down_parity.py")
_e("PA-1", "PAR-01", "EXACT", "active", "Parity ledger: the design's odd sources are the gamma mixed flux (basis rotation, physical only via the condensate), the condensate's odd components (u^c, e^c, nu^c, L, H_u), P2's torus displacement with the 13 odd complex-structure moduli (tails, 1e-5) and torus Wilson lines (even values or saddles); everything else is even. None reaches Q, d^c or H_d at first order with a physical effect.", "mtft.matter.parity_audit", "test_pa01_parity_audit.py")
_e("PA-2", "PAR-01", "NUMERICAL", "active", "The floor's one loophole, an up-sector local arm, needs |v_u| >= 3.1 z V_us (0.18 at z = 0.25), which puts m_u/m_c at 0.048-0.11, 24-56 times the data: closed unless tuned.", "mtft.matter.parity_audit", "test_pa01_parity_audit.py")
_e("PA-3", "PAR-01", "EXACT", "active", "The product's complex-structure deformations split into 37 even (H^1(T_X), H^1(T_E)) and 13 odd (H^1(O_X) (x) H^0(T_E)); the odd ones move the torus origin along the curve and reach the jet point only through tails.", "mtft.matter.parity_audit", "test_pa01_parity_audit.py")
_e("PA-4", "PAR-01", "STRUCTURAL", "caveat", "With tails capped at 13.8 the two-point design predicts |V_ub| >= 0.0084, 2.3 times the measured value: ruled out as a flavour model. Redesigns: a B-stack field with an odd profile (not in the spectrum) or a different home for the left-handed top (first question: does y_t = 0.70 survive H_u bridging two points).", "mtft.matter.parity_audit", "test_pa01_parity_audit.py", "CC-60: both redesigns it left open are now closed (OM-2, YB-1)")
_e("OM-1", "OM-01", "EXACT", "active", "Under w -> -w the symmetric bundle O(N O) with the natural lift has 1 + floor(N/2) even and floor((N-1)/2) odd sections (pole orders), matching the Lefschetz sum ((-1)^N + 3)/2 over the four 2-torsion points: odd modes are forced from N = 3 up.", "mtft.matter.odd_modes", "test_om01_yb01_experiments.py")
_e("OM-2", "OM-01", "EXACT", "active", "Every block has torus degree 0 (one unit costs 24 chiral families, TP-01; gamma charges are Poincare-type), so zero modes are constant along the torus and even; the only forced odd modes are the w-jet families (states, not sources). No down-sector field that could carry an odd vev or coupling has an odd mode: PA-1's verdict is topological.", "mtft.matter.odd_modes", "test_om01_yb01_experiments.py")
_e("OM-3", "OM-01", "EXACT", "active", "Giving a B-stack block the three units of torus flux an odd mode needs would cost 72 chiral families.", "mtft.matter.odd_modes", "test_om01_yb01_experiments.py")
_e("YB-1", "YB-01", "ESTIMATE", "active", "Pre-registered (y_t >= 0.5): a top whose halves sit at the jet point and the Fricke home couples through the bridge 4 (r1/r2)^2 t(s) = 0.41-0.45 (image-summed tail t = 0.25-0.28), so y_t <= 0.29-0.32 with the marginal local 0.70, and 0.17-0.27 with AG-01's curvature factors: FAIL by >= 1.6.", "mtft.matter.bridged_top", "test_om01_yb01_experiments.py")
_e("YB-2", "YB-01", "STRUCTURAL", "active", "Both redesigns are closed: the two-point design on X0(143) x 143a1 with this stack does not carry the quark flavour structure. The arithmetic results (AG-01's kernel, FH-01's Fricke placement, the r concordance) stand on their own.", "mtft.matter.bridged_top", "test_om01_yb01_experiments.py")
_e("CC-60", "correction", "EXACT", "active", "Caveats PA-4: the two redesigns it left open are closed — the B-stack odd source is excluded topologically (OM-2) and the bridged top fails its pre-registered test (YB-1).", "mtft.matter.bridged_top", "test_om01_yb01_experiments.py")
_e("LEP-6", "LEP-01", "NUMERICAL", "active", "The equal-overlap texture has several exact solutions per sector (from a fixed grid of starts, s1 >= 0: up 3, down 2, leptons 5). On the rho branch nearest the coherent value 1/2 every sector has a charge-0-dominated fit - up (1, 0.082, 0.003), down (1, 0.221, 0.029), leptons (1, 0.339, 0.031) - while leptons also fit with the charge-1 jet dominant, (1, 3.26, -0.31): the texture does not decide which jet dominates.", "mtft.matter.leptons", "test_lep01_leptons.py")
_e("CC-61", "correction", "EXACT", "active", "Retracts LEP-4: its 'leptons need the charge-1 jet' was the optimizer's path. The texture has several exact solutions per sector, related by s1 -> -s1 and by zero flips (CC-40), and leptons also fit charge-0 dominated (LEP-6). Exposed when a SciPy upgrade changed which solution least_squares reached first; fit_alignment now returns a stated canonical representative and all_alignments the full set.", "mtft.matter.leptons", "test_lep01_leptons.py")
_e("CC-62", "correction", "EXACT", "active", "Bookkeeping: relabels the parity audit's wave from PA-01, which is Path A's label, to PAR-01; its claim ids PA-1 to PA-4 are unchanged and distinct from Path A's PA1-1 and PA1-2.", "mtft.matter.parity_audit", "test_pa01_parity_audit.py")
_e("SQ-1", "SQ-01", "EXACT", "active", "X0(N)* = X0(N)/<W_p, W_q> over the 105 levels N = pq with p < q supersingular: a sphere at 21, an elliptic curve at 13 (57, 58, 65, 77, 82, 91, 118, 123, 141, 142, 143, 145, 155), genus >= 2 at 71. Route 1 (newform signs, PARI, 99 levels) and route 2 (class-number fixed points with Eichler symbols and the Lefschetz formula, pure Python, all 105) agree wherever both run.", "mtft.matter.star_quotients", "test_sq01_star_quotients.py")
_e("SQ-2", "SQ-01", "NUMERICAL", "active", "Each of the 13 elliptic quotients has analytic rank 1 (PARI lfunorderzero); odd rank is forced, since all signs +1 give Fricke sign +1 and root number -1. X0(143) is not the only supersingular semiprime level that folds onto a rank-1 elliptic curve.", "mtft.matter.star_quotients", "test_sq01_star_quotients.py")
_e("SQ-3", "SQ-01", "EXACT", "active", "What singles out 143: the twin levels 15, 35, 143, 323, 899 have star genus 0, 0, 1, 5, 12, so 143 is the only twin level with an elliptic quotient; 77 and 143 are the only consecutive-prime levels with one; dim S2^new = p (the smaller prime) at 11 levels, with p, q consecutive only at 143; the Galois-orbit pattern (1, 4, 6) occurs only at 143.", "mtft.matter.star_quotients", "test_sq01_star_quotients.py")
_e("SQ-4", "SQ-01", "EXACT", "active", "143's nearest sibling is 123 = 3 x 41: the only other level of index 168 and, with 143, the only torsion-free genus-13 level; it has four cusps and a rank-1 elliptic quotient, and new dimension 7 (orbits 1, 1, 2, 3) against 143's 11 (1, 4, 6).", "mtft.matter.star_quotients", "test_sq01_star_quotients.py")
_e("SQ-5", "SQ-01", "EXACT", "active", "Moonshine cross-check: every level in the scan whose star quotient is a sphere (21 with two primes; 30, 42, 66, 70, 78, 105, 110 with three) is the order of an element of the Monster (GAP CTblLib, 73 element orders); 143 is not, and among the semiprime levels the converse fails at 57 and 93.", "mtft.matter.star_quotients", "test_sq01_star_quotients.py")
_e("SQ-6", "SQ-01", "EXACT", "active", "With three or four supersingular primes and N <= 700 (75 levels; both routes agree) the star quotient is an elliptic curve at 102, 114, 130, 138, 174, 182, 190, 195, 210, 231, 238 and a sphere at 30, 42, 66, 70, 78, 105, 110; each extra prime doubles the cusps and the Atkin-Lehner group.", "mtft.matter.star_quotients", "test_sq01_star_quotients.py")
_e("SQ-7", "SQ-01", "STRUCTURAL", "active", "The exact obstructions behind pieces IX and X do not use the level: DS-1's stack pattern, the odd-mode count (an odd B-stack mode costs 3(2g - 2) chiral families: 24 to 96 over the torus levels, 72 at 143, OM-3), QL-1's dressing bound and CI-2's universality. DS-4's tail cap and BL-01's Wilson-line numbers were computed on X0(143) x 143a1 only.", "mtft.matter.star_quotients", "test_sq01_star_quotients.py")
_e("SQ-8", "SQ-01", "STRUCTURAL", "active", "Pre-registered for IV.6: a rule that selects the level must be stated before it is evaluated on the 13 torus levels, and passes only if it selects 143 and rejects the other twelve, 123 and 77 included; SQ-3's distinctions were found after the fact and do not count as such a rule.", "mtft.matter.star_quotients", "test_sq01_star_quotients.py")
_e("TR-1", "TR-01", "EXACT", "active", "Time reversal on a gauge coupling tau = theta/2pi + 4pi i/g^2 is tau -> -conj(tau); its fixed lines theta = 0 and theta = pi generate under SL(2,Z) the two conjugacy classes of reflections of PGL(2,Z) — Farey edges (fixed form of content 2, endpoint determinant 1) and Farey medians (content 1, determinant 2) — so no duality carries theta = 0 to theta = pi; the two routes agree on all 106 reflections (212 matrices) with entries <= 12.", "mtft.matter.time_reversal", "test_tr01_time_reversal.py")
_e("TR-2", "TR-01", "EXACT", "active", "The oloid move q -> -q/(1+q) (mirror |tau+1| = 1) and the triangle mirror n -> -1-n (Re tau = -1/2) are both of the theta = pi class, and so is 143a1's period lattice: its discriminant -1859 < 0 makes the lattice rhombic with Re tau = 1/2 exactly and E(R) a single circle.", "mtft.matter.time_reversal", "test_tr01_time_reversal.py")
_e("TR-3", "TR-01", "EXACT", "active", "The thirteen star quotients of SQ-01 as curves: in each (+,+) isogeny class exactly one curve has modular degree 4 = |<W_p,W_q>| and is the quotient — 57a1, 58a1, 65a2 (not the optimal 65a1, of degree 2), 77a1, 82a1, 91a1, 118a1, 123b1, 141d1, 142b1, 143a1, 145a1, 155c1; nine have one real circle (theta = pi) and four two (82, 141, 142, 145: theta = 0). PARI 2.17.2 elldata, frozen and reproduced.", "mtft.matter.time_reversal", "test_tr01_time_reversal.py")
_e("TR-4", "TR-01", "EXACT", "active", "The root number is the parity of the completed L-function under t -> -t: from Lambda(s) = epsilon Lambda(2-s) with real coefficients, Lambda(1+it) = epsilon conj(Lambda(1+it)), so epsilon = -1 makes Lambda purely imaginary and odd and forces the zero at t = 0 — SQ-2's odd rank restated; all thirteen quotients are odd, 11a1 is even. PARI's values agree but assume the functional equation, so they are consistency, not an independent check.", "mtft.matter.time_reversal", "test_tr01_time_reversal.py")
_e("TR-5", "TR-01", "EXACT", "active", "A CM point is time-reversal symmetric on X(1) iff its form class is ambiguous (real j), and the class is read off the reduced form: B = 0 is theta = 0, |B| = A or A = C is theta = pi. W_143's twenty fixed points lie over the ten classes of discriminant -143 and the ten of -572, of which four are real on X(1): (1,0,143) and (11,0,13) of class theta = 0, (1,1,36) and (6,1,6) of class theta = pi; W_13's four lie over the two classes of -52, one of each mirror class. The level-143 real structure (product_surface: CP pairs the W_13 points) is a finer question, open.", "mtft.matter.time_reversal", "test_tr01_time_reversal.py")
_e("TR-6", "TR-01", "STRUCTURAL", "superseded", "Pre-registered test for I.4, sealed as PR-S1 before any candidate exists: a lift fixing the strong coupling at an arithmetic point passes without an axion iff the point lies on a theta = 0 mirror and arg det(M_u M_d) = 0; a theta = pi mirror is time-reversal symmetric at theta-bar = pi (excluded), no mirror needs an axion.", "mtft.matter.time_reversal", "test_tr01_time_reversal.py", "CC-63: theta-bar = theta + arg det, so a theta = pi point with arg det = pi passes; replaced by TR-8 (seal PR-S2)")
_e("TR-8", "TR-01", "STRUCTURAL", "active", "Pre-registered test for I.4, sealed as PR-S2 before any candidate exists: with theta-bar = theta + arg det(M_u M_d), a lift fixing the strong coupling at a CM point passes without an axion iff the point lies on a mirror whose class matches the quark-mass phase (theta = 0 with arg det = 0, theta = pi with arg det = pi, mod 2 pi; a point on both classes, such as tau = i, with either); any other combination is theta-bar = pi, a time-reversal-symmetric vacuum that is not ours; no mirror fails unless an axion exists. Numerical candidates classify to tolerance only. Outcome pending.", "mtft.matter.time_reversal", "test_tr01_time_reversal.py")
_e("TR-7", "TR-01", "EXACT", "active", "The fold n -> T(n) is two-to-one with mirror-image preimages n and -1-n, so the iteration F = 2rT of the oloid thread cannot be run backwards: its irreversibility, and hence its chaos, lives in the chosen iteration, not in the move, which is an involution.", "mtft.matter.time_reversal", "test_tr01_time_reversal.py")
_e("PR-1", "PR-01", "STRUCTURAL", "active", "A pre-registered rule is now sealed by the SHA-256 of its id, statement, evaluating code, parameters and pass window, dated before evaluation; verify() recomputes it from the code as it stands and evaluate() refuses a rule that changed after sealing, so a rule can only be re-sealed under a new id with the old entry kept (append-only, as the CC corrections).", "mtft.matter.prereg", "test_pr01_prereg.py")
_e("PR-2", "PR-01", "STRUCTURAL", "active", "The six earlier pre-registered tests T0–T5 were stated in prose before evaluation but never hash-sealed; they are listed as legacy and not re-sealed after the fact. PR-S1 (the I.4 strong-CP rule) is the first sealed entry.", "mtft.matter.prereg", "test_pr01_prereg.py")
_e("PR-3", "PR-01", "EXACT", "active", "The trials counter for IV.6: sixteen properties have been tried as reasons for 143 on the thirteen torus levels, none pre-registered; four single it out (twin primes; new dimension p with consecutive primes; the orbit pattern (1,4,6), which eight of the thirteen levels would also pass in their own version; N = 7 mod 8), fourteen include it. Every property was chosen by looking at 143, so the record is a look-elsewhere account, not evidence (AG-D5, SQ-8).", "mtft.matter.prereg", "test_pr01_prereg.py")
_e("GF-1", "GF-01", "EXACT", "active", "The eight-dot engine: a rank-8 parent is eight dots (one circle U(1) each, the maximal torus T^8); grouping the dots chooses the forces — n coincident dots are U(n) with n circles and n(n-1) lines inside as carriers — and the lines between groups are the particles: the Pati–Salam grouping (4,2,2) has 24 carriers and 40 particle states, the Standard-Model grouping U(3) x U(1) x U(2) x U(1)^2 has 16 carriers (the 12 of the Standard Model and four extra U(1)s) and 48; the Standard-Model fields are its difference lines with PS-01's hypercharges, and the four Yukawa couplings are the four triangles of dots whose third side is the Higgs, H_u on (L, A2) and H_d on (L, B) as DS-01 has them. Reproduces PS-01's branching, DS-01's charge table (the conjugate orientation) and PV-01's 28 blocks of Lambda^2(8); eight dots can be grouped in 22 ways.", "mtft.matter.forces", "test_gf01_forces.py")
_e("GF-2", "GF-01", "STRUCTURAL", "superseded", "The touch scan, sealed as PR-S3 (DS-01's first-order criterion q_s . q_f != 0) and run on the three block menus: in the U(8) menu the only Standard-Model-singlet block is the nu^c line on A1-A2 and it reaches L, u^c, e^c, nu^c, H_u and never Q, d^c, H_d (DS-1 as a menu statement, FAIL); the sum lines B+A2, A1+B and Lambda^2(L) of SO(16) and six spinor sheets of E8 do reach the down sector (PASS). With GF-7, the only blocks that reach d^c at first order live in parents that cannot give three families: piece IX's down-sector wall is a statement about every consistent parent column, not about one design.", "mtft.matter.forces", "test_gf01_forces.py", "CC-64: over-claimed the scope — PV-01's non-supersymmetric U(8) carries the same sum lines (as fermions) and was not scanned; replaced by GF-13")
_e("GF-3", "GF-01", "STRUCTURAL", "superseded", "Charge quantisation, sealed as PR-S4: the generator (omega, -1, e^{2 pi i/6}) of the centre acts trivially on every Standard-Model line, t/3 + d/2 + Y integer, so the gauge group is [SU(3) x SU(2) x U(1)]/Z6 or a quotient and every free particle carries a whole electric charge, Q = (2/3) t mod 1 (PASS). The rule passes for every odd T_3R coefficient of the anomaly-free family, so it is necessary and not what fixes hypercharge.", "mtft.matter.forces", "test_gf01_forces.py", "CC-64: the global-form reading was backwards (Z6 trivial on the matter allows G/Z6 or any of its covers, not a further quotient); seal PR-S4 superseded by PR-S5; replaced by GF-10")
_e("GF-4", "GF-01", "EXACT", "active", "Hypercharge by two routes (E2). Route A: anomaly freedom of one generation of lines on the stack U(1)s leaves the two-dimensional space <T_3R, B-L>, not one direction; Y(Q) = 1/6 fixes the B-L coefficient, and a neutral Higgs component — the photon surviving electroweak breaking — fixes the T_3R coefficient a to +-1 (a = 3 passes anomalies and Z6 but gives a charged Higgs); a = -1 is the relabelling B <-> A2 (the u <-> d swap). Route B: the Pati–Salam embedding Y = T_3R + (B-L)/2 with (B-L)/2 = sqrt(2/3) T_15. Both land on (1/6, -1/2, 0, 1/2, -1/2).", "mtft.matter.forces", "test_gf01_forces.py")
_e("GF-5", "GF-01", "EXACT", "active", "The couplings are the shape of the force torus: a unit of T_3 is 1/g long and a unit of Y is 1/g', so the photon, the diagonal Q = T_3 + Y, has length 1/e by Pythagoras (1/e^2 = 1/g^2 + 1/g'^2, exact) and the weak angle is the diagonal's tilt (28.74 degrees at m_Z, NUMERICAL); GC-01's matching alpha_Y^-1 = alpha_R^-1 + (2/3) alpha_4^-1 is the same theorem on the Pati–Salam torus with Y = T_3R + sqrt(2/3) T_15, and its R is a ratio of cycle-length differences, quantised by the exceptional charges (GC-3). Each coupling with its theta is the point tau = theta/2 pi + i/alpha of the upper half-plane; at theta = 0 these sit on the theta = 0 mirror by assumption and are not candidates for PR-S2.", "mtft.matter.forces", "test_gf01_forces.py")
_e("GF-6", "GF-01", "EXACT", "active", "The U(8) column of I.1 (supersymmetric parent, PV-02's twist): net chirality is linear in the stack twist indices, net = q . phi, so the exact Standard Model is a linear Diophantine system of rank 3 in five unknowns; it recovers PV-02's conditions phi_c - phi_L = 3, phi_B - phi_c = 3, phi_A1 + phi_A2 - 2 phi_c = 3 (18 solutions in the box of 4, every one with six doublet pairs). PV-01's non-supersymmetric U(8) with Lambda^2(8) + 8 x 8, whose indices are bilinear, is cited (60 and 156 assignments), not recomputed.", "mtft.matter.forces", "test_gf01_forces.py")
_e("GF-7", "GF-01", "EXACT", "superseded", "The SO(16) and E8 columns are closed by parity: a parent containing both roots e_c - e_L and e_c + e_L has two (3, 2) lines with chiralities phi_c - phi_L and phi_c + phi_L; with the stack hypercharge both are quark doublets and their net is 2 phi_c, never 3, and with any shift of the hypercharge the sum line is a chiral exotic doublet with no partner, forcing phi_c + phi_L = 0 against phi_c - phi_L = 3. The full systems are inconsistent over the rationals at every shift in (1/48) Z on [-2, 2] (193 each; the coincidences of block hypercharges all lie there). Conditional on the supersymmetric twist and the Standard Model embedded through U(8) with hypercharge from the stacks; a different embedding of E8 is not addressed.", "mtft.matter.forces", "test_gf01_forces.py", "CC-64: 'cannot give three quark doublets' is false for E8, whose sheets allow three with three chiral exotic doublets; the rational obstruction is in the lepton rows; replaced by GF-11")
_e("GF-8", "GF-01", "EXACT", "superseded", "The clock of twelve: SL(2,Z) is generated by S (order 4, S^2 = -1) and ST (order 6) and its abelianisation is Z/12, the character eta^2 carries (Delta = eta^24 has weight 12), with PSL(2,Z)^ab = Z/6; at level 143 the twelve is g - 1 = (11 + 13)/2, the spin twist (12, 0) and the pivot of the five means of 11 and 13 (HM x AM = 143, AM x CHM = 145). The twelve directions of the colour plane (six weights, six roots, 30 degrees apart, lengths 1 : sqrt 3) are the roots of G2 (Weyl group of order 12), and the Standard Model has twelve carriers; the Z6 of the Standard Model and the Z/6 of PSL(2,Z) match in size only — no map is claimed (AG-D5). On X(1) the golden loop (trace 3, discriminant 5, length 4 log phi) passes through i and crosses the theta = pi mirror at (1 + i sqrt5)/2, discriminant -20; the twelve loop (trace 4, discriminant 12, length 2 log(2 + sqrt3)) passes through rho and crosses at i sqrt2 (-8, twice), i sqrt3 (-12) and (1 + i sqrt11)/2 (-11): mirror crossings are CM points of the matching TR-01 class. The golden loop is reversed by the half-turn S (phi has norm -1); the twelve loop is reversed only by a mirror (2 + sqrt3 has norm +1). X(5) is the icosahedron, twelve cusps at (0, +-1, +-phi): the one exact meeting of twelve and phi, at level 5.", "mtft.matter.forces", "test_gf01_forces.py", "CC-64: the twelve loop also crosses (1 + i sqrt11)/2 twice (a second self-crossing, on the theta = pi mirror), and 'the one place' was an unsupported superlative; replaced by GF-12")
_e("GF-9", "GF-01", "EXACT", "active", "The shortest closed loop of X0(143) is the twelve loop: the golden loop closes at N iff x^2 - 3x + 1 = 0 is solvable mod N (odd squarefree N: 5 a square mod every prime of N; never at even N, whose traces are even), and (5/13) = -1 excludes it, so the systole has discriminant 12 and length 2 log(2 + sqrt3), the unit of Q(sqrt3) that is the dodecagon's chord-to-side ratio tan 75 degrees — not phi, which is not in the dodecagon's field Q(sqrt2, sqrt3) (the sin 15 = (phi - 1)/sqrt2 of the Gemini note is false; sin 18 = (phi - 1)/2 is the golden sine). Among the thirteen torus levels the twelve loop is the systole at 118, 141, 142, 143 and the golden one at 145, 155; logged as trial X17 (selects four of thirteen, includes 143), computed before it was logged, so tried after looking and not evidence.", "mtft.matter.forces", "test_gf01_forces.py")
_e("GF-10", "GF-01", "STRUCTURAL", "active", "Charge quantisation, sealed as PR-S5 (PR-S4 superseded the same day, CC-64): the generator (omega, -1, e^{2 pi i/6}) of the centre, U(1)_Y acting by e^{2 pi i Y}, acts trivially on every Standard-Model line, t/3 + d/2 + Y integer, so the matter allows the gauge group [SU(3) x SU(2) x U(1)]/Z6 or any of its covers, and the electric charges of a block's components are (2/3) t mod 1: every free particle carries a whole charge (PASS). The rule passes for every odd T_3R coefficient of the anomaly-free family, so it is necessary and not what fixes hypercharge.", "mtft.matter.forces", "test_gf01_forces.py")
_e("GF-11", "GF-01", "EXACT", "active", "The SO(16) and E8 columns of I.1 are closed (supersymmetric twist, Standard Model through U(8) with hypercharge from the stacks). SO(16): the roots e_c - e_L and e_c + e_L are both quark doublets, so the net count is 2 phi_c, never 3 (with a hypercharge shift the sum line is a chiral exotic with no partner, forcing phi_c + phi_L = 0 against phi_c - phi_L = 3), and over the rationals the lepton rows already conflict: net(L) + net(e^c) = 0 against 3 + 3. E8: the sheets add three more Q-type blocks, so three quark doublets are possible (phi = (6, 0, 0, 0, 0)) but only with three chiral exotic (3, 2)_{-5/6} doublets, whose row is minus the Q row, and the lepton rows conflict the same way. Both systems are inconsistent over the rationals at every shift in (1/48) Z on [-2, 2] (193 each), at every special shift (where block hypercharges coincide: denominators 1, 2, 4 and 1, 2, 4, 6) and at a generic one, hence for every real shift. Neither column gives the exact Standard Model; a different embedding of E8 (the heterotic SU(5) x U(1)^5 line-bundle route) is not addressed.", "mtft.matter.forces", "test_gf01_forces.py")
_e("GF-12", "GF-01", "EXACT", "active", "The clock of twelve: SL(2,Z) is generated by S (order 4, S^2 = -1) and ST (order 6; a 120-degree turn about rho, the corner where TR-01's oloid and triangle mirrors, both of the theta = pi class, meet at 60 degrees) and its abelianisation is Z/12, the character eta^2 carries (Delta = eta^24 has weight 12), with PSL(2,Z)^ab = Z/6; Z/12's subgroups have orders 1, 2, 3, 4, 6, 12. At level 143 the twelve is g - 1 = (11 + 13)/2, the spin twist (12, 0) and the pivot of the five means of 11 and 13 (HM x AM = 143, AM x CHM = 145). The twelve directions of the colour plane (six weights, six roots, 30 degrees apart, lengths 1 : sqrt 3) are the roots of G2 (Weyl group of order 12), the Standard Model has twelve carriers, and the Weyl group of the U(3) x U(2) grouping has order 12; the Z6 of the Standard Model and the Z/6 of PSL(2,Z) match in size only — no map is claimed (AG-D5). On X(1) the golden loop (trace 3, discriminant 5, length 4 log phi) passes through i and crosses the theta = pi mirror at (1 + i sqrt5)/2, discriminant -20; the twelve loop (trace 4, discriminant 12, length 2 log(2 + sqrt3)) passes through rho and crosses the mirrors at i sqrt2 (-8, twice), i sqrt3 (-12, once) and (1 + i sqrt11)/2 (-11, twice) — two transversal self-crossings, one on each mirror class; a loop with real endpoints alpha, alpha' crosses the theta = 0 mirror at i sqrt(-alpha alpha'), so every mirror crossing is a CM point of the class TR-01 assigns. The golden loop is reversed inside SL(2,Z) by the half-turn S (phi has norm -1); the twelve loop is reversed only by a mirror (2 + sqrt3 has norm +1: x^2 - 3y^2 = -1 is impossible mod 3). X(5) is the icosahedron, twelve cusps at (0, +-1, +-phi): a place where twelve and phi meet exactly, at level 5.", "mtft.matter.forces", "test_gf01_forces.py")
_e("GF-13", "GF-01", "STRUCTURAL", "active", "The touch scan, sealed as PR-S3 (DS-01's first-order criterion q_s . q_f != 0) and run on the three supersymmetric block menus: in the U(8) menu the only Standard-Model-singlet block is the nu^c line on A1-A2 and it reaches L, u^c, e^c, nu^c, H_u and never Q, d^c, H_d (DS-1 as a menu statement, FAIL); the sum lines B+A2, A1+B and Lambda^2(L) of SO(16) and six spinor sheets of E8 do reach the down sector (PASS), but neither of those columns gives the exact Standard Model (GF-11). PV-01's non-supersymmetric U(8) carries the same sum lines as fermions only — its scalars are the adjoint's internal components, the difference lines — and was not scanned. Within the supersymmetric menus the down-sector wall of piece IX is therefore a statement about the parent, not about one design.", "mtft.matter.forces", "test_gf01_forces.py")
_e("CC-64", "correction", "EXACT", "active", "Supersedes GF-2, GF-3, GF-7 and GF-8 by GF-13, GF-10, GF-11 and GF-12, and seal PR-S4 by PR-S5, on the day of sealing after independent review: GF-2 over-claimed its scope (PV-01's non-supersymmetric U(8) has the sum lines as fermions and was not scanned); GF-3 and PR-S4 read the global form backwards (Z6 trivial on the matter allows G/Z6 or any of its covers, not a further quotient — the criterion is unchanged); GF-7's 'cannot give three quark doublets' is false for E8, where the sheets allow three with three chiral exotic (3, 2)_{-5/6} doublets, and the rational obstruction in both columns is in the lepton rows, net(L) + net(e^c) = 0; GF-8 missed the twelve loop's second self-crossing at (1 + i sqrt11)/2, called ST a 60-degree turn (it is 120 degrees about rho, where two mirrors of the same class meet at 60 degrees) and used an unsupported superlative. The review confirmed every number of the wave from its own construction of the root systems of SO(16) and E8.", "mtft.matter.forces", "test_gf01_forces.py")
_e("PG-1", "PG-01", "EXACT", "active", "The shape modulus r = A_X/A_E sits in a cosh well: with phi = log r the flux landscape of PV-01 (A = 19, B = 11) is E(r)/E* = cosh(phi - phi*), floor at the self-dual point r* = sqrt(19/11), and the well's curvature at the floor is exactly 1 in units of the floor energy E* = 8 pi^2 sqrt(AB) — a sink of the gradient flow. Reading phi as the canonical field is the natural log metric of a ratio modulus and is not derived here; the identity is exact.", "mtft.matter.vacuum_atlas", "test_pg01_energy.py")
_e("PG-2", "PG-01", "EXACT", "superseded", "The critical-point atlas of the potentials the programme has, in the eight-types language (eigenvalue sign and reality patterns of the linearised flow): the shape is a sink (PG-1); the volume has no finite critical point, both Einstein-frame terms falling with Vol, so the gradient flow runs to decompactification (PV-01); the condensate's D-term potential in the fields (v, vbar) has a zero Hessian eigenvalue along vbar at its minimum v^2 = (8/13) xi — non-hyperbolic — which a mass term m^2 (v^2 + vbar^2) lifts to 4 m^2 with the minimum at v^2 = (8/13)(xi - m^2), a sink (CO-1); the relative-U(1) Wilson line on its torus has a two-dimensional sink at the jet vacuum theta = 0 and a two-dimensional source at the untwisted point theta_eta, the two Hessians being negatives of each other, for all three even spin structures (the full Hessians behind PA1-1's path statement); the bosonic adjoints are sinks (M05-1) and the one-loop Casimir has no critical point in A_X (MS-6). No saddle appears anywhere, and no spiral: spirals need time.", "mtft.matter.vacuum_atlas", "test_pg01_energy.py", "CC-65: three results were stated without their hypotheses (the volume runaway needs both coefficients positive; the condensate lift needs 0 < m^2 < xi; the Wilson-line Hessians are exact in PA-01's product approximation, not in the full sum); replaced by PG-4")
_e("PG-3", "PG-01", "STRUCTURAL", "superseded", "With Hubble friction 3H a sink of mass m is a spiral (the eigenvalues (-3H +- sqrt(9H^2 - 4m^2))/2 complex) iff m > 3H/2 and a node otherwise, so the type of every sink of the atlas in a cosmological run is set by m/H, which the programme has not fixed. The DIAGNOSTIC toy run of the shape modulus, phi'' + 3H phi' + sinh(phi - phi*) = 0 in units of the floor curvature, shows spiral capture at the self-dual point for H = 0.2 m (18 floor crossings) and in a radiation era H = 1/2t, a node for H = m, while log Vol under the same friction rises without bound; the normalisation of H against the modulus mass is not derived. The gate a big-bang-to-matter run must pass is recorded as I.7: a declared parent (I.1), a vacuum energy from the parent action with a volume stationary point (I.6; GS-1), the couplings at the stabilised point (GC-01), a cosmological background, and then standard physics at confinement and nucleosynthesis.", "mtft.matter.vacuum_atlas", "test_pg01_energy.py", "CC-65: the crossing count depends on the run length and capture rests on the energy argument, not on the run; the volume's rise is logarithmic in the toy; replaced by PG-5")
_e("PG-4", "PG-01", "EXACT", "caveat", "The critical-point atlas of the potentials the programme has, in the eight-types language (eigenvalue sign and reality patterns of the linearised flow), each result with its hypothesis: the shape is a sink (PG-1); the volume has no finite critical point when both Einstein-frame coefficients are positive, as PV-01 finds them, both terms then falling with Vol, so the gradient flow runs to decompactification; the condensate's D-term potential in the fields (v, vbar) has a zero Hessian eigenvalue along vbar at its minimum v^2 = (8/13) xi — non-hyperbolic — which a mass term m^2 (v^2 + vbar^2) with 0 < m^2 < xi lifts to exactly 4 m^2 with the minimum at v^2 = (8/13)(xi - m^2), a sink (CO-1 made quantitative); the relative-U(1) Wilson line on its torus has a two-dimensional sink at the jet vacuum theta = 0 and a two-dimensional source at the untwisted point theta_eta, the two Hessians negatives of each other, for all three even spin structures — exact in PA-01's product approximation, the standing of PA1-1 itself, whose path statement these are the full Hessians behind; the bosonic adjoints are sinks (M05-1) and the one-loop Casimir has no critical point in A_X (MS-6). No saddle appears anywhere, and no spiral: spirals need time.", "mtft.matter.vacuum_atlas", "test_pg01_energy.py", "CC-66: 'No saddle appears anywhere' holds only along PA-01's straight path, and conflicted with BL-3 when filed; on the whole torus the Wilson line has two saddles at the other two half-periods (PG-6). The rest of the atlas stands.")
_e("PG-5", "PG-01", "STRUCTURAL", "active", "With Hubble friction 3H a sink of mass m is a spiral (the eigenvalues (-3H +- sqrt(9H^2 - 4m^2))/2 complex) iff m > 3H/2 and a node otherwise, so the type of every sink of the atlas in a cosmological run is set by m/H, which the programme has not fixed. Capture of the shape modulus at the self-dual point is guaranteed by the energy argument: E = phi'^2/2 + cosh(phi - phi*) - 1 has dE/dt = -3H phi'^2 <= 0 for any H(t) > 0 and the well has one critical point, so every trajectory ends at the floor; the DIAGNOSTIC toy run, phi'' + 3H phi' + sinh(phi - phi*) = 0 in units of the floor curvature, only illustrates it: a spiral for H = 0.2 m (18 floor crossings in a run of length 60/m, a count that grows with the run) and in a radiation era H = 1/2t, a node for H = m; log Vol under the same constant friction rises without bound but only like (2/3) log t at late times in the toy. The normalisation of H against the modulus mass is not derived. The gate a big-bang-to-matter run must pass is recorded as I.7: a declared parent (I.1), a vacuum energy from the parent action with a volume stationary point (I.6; GS-1), the couplings at the stabilised point (GC-01), a cosmological background, and then standard physics at confinement and nucleosynthesis.", "mtft.matter.vacuum_atlas", "test_pg01_energy.py")
_e("CC-65", "correction", "EXACT", "active", "Supersedes PG-2 and PG-3 by PG-4 and PG-5 on the day of filing after independent review, and corrects the arithmetic half of PG-01 in the Legend and report: the wave's first statement that marking by w_n moves the energy off the zeros of zeta was false — exactly U_D(beta) = -zeta'/zeta(beta) - zeta''(beta+1)/zeta'(beta+1), so the marked energy keeps every pole of the von Mangoldt series at the zeros (residue -1, checked at rho_1) and adds poles at the zeros of zeta' shifted by one; what is RH-blind is Z_D and the summatory function sum_{n<=x} w_n = -zeta'(2) x - log^2 x/4 - (ln 2 pi) log x/2 + O(1) (the error of the density is O(log^2 x/x), not O(log x/x)). Also: the 12 multiplying ln A in -zeta'(2) is -1/zeta(-1) = 2 pi^2/zeta(2) by the functional equation at s = 2, not 'zeta(-1) in front'; the Bendersky identity is the definition of A_{k-1} rearranged, not a theorem about the alphabet; chi(SL(2,Z)) = -1/12 is the rational (Wall–Serre) Euler characteristic of the amalgam, equal to zeta(-1) by the K = Q case of Harder's theorem, and |SL(2,Z)^ab| = 12 = 1/|chi| is a coincidence of size, not a map (AG-D5); the Bost–Connes paragraph now says what the marked gas is (its own Gibbs construction, not a KMS state of that algebra) and that nothing follows from the coincidence of the parameter value beta = 1. The matter half: three results stated without their hypotheses (PG-4) and a run-length-dependent count presented as a result (PG-5). The review confirmed every number of the wave independently (the Hessians, the Glaisher and Bendersky identities, the genus formula, the toy run).", "mtft.matter.vacuum_atlas", "test_pg01_energy.py")
_e("PG-6", "PG-01", "EXACT", "active", "On the whole torus R^2/Z^2 of the relative-U(1) Wilson line, V(theta) = -2 sum_{odd w} |w|^-8 cos(2 pi theta . w) has, for each even spin structure, critical points at the four half-periods (EXACT: V(-theta) = V(theta)) and no others (NUMERICAL, two routes: a Newton census, and a winding-number count on a 1024 x 1024 grid with a Lipschitz exclusion and a contraction bound): the sink at the jet vacuum theta = 0, the source at the untwisted point theta_eta = eps/2, and two saddles at the other two half-periods, all four nondegenerate — a Morse function on a torus has #min - #saddle + #max = chi(T^2) = 0, so at least two saddles, and exactly two with one minimum and one maximum. In the real spin structure eps = (0, 1) both saddles sit at V = 0 exactly: (m, n) -> (-m - n, n) keeps |m + n tau| because Re tau = 1/2 and flips the parity of m for odd n, so the odd windings cancel in pairs (V = -3.178063, 0, 0, +3.178063 at sink, saddles, source); for the conjugate pair the values are -5.991688, -2.813625, +2.813625, +5.991688, and V_(1,0)(0) = V_(1,0)(0, 1/2) + V_(0,1)(0) by the same pairing. The curvatures that set the Wilson-line masses are the eigenvalues of G^-1 H in 143a1's Hodge metric G (det 1): 37.394 and 128.985 at the jet vacuum for eps = (0, 1), a mass ratio of 1.857 — the theta-coordinate Hessian's 28.893 and 166.935 have the same product but would give 2.404; the conjugate structures, mirror images under the curve's real structure, get identical metric curvatures (60.834, 194.868) and different theta-coordinate ones. Exact in PA-01's product approximation, as PA1-1 is, which stands: the jet vacuum is the only minimum and the saddles are the passes for winding the holonomy. The saddle character of these half-periods was already BL-3's (for the B–L Wilson line); new here (2026-10-14) are the complete census, the exact zeros and the metric curvatures.", "mtft.matter.vacuum_atlas", "test_pg01_wilson_torus.py")
_e("CC-66", "correction", "EXACT", "active", "Caveats PG-4 by PG-6 (2026-10-14): the atlas's 'No saddle appears anywhere' held only along PA-01's straight path from the jet vacuum to the untwisted point, and it also conflicted, when filed, with BL-3 (CC-54), which had already found saddles at these half-periods for the B–L Wilson line, whose one-loop potential has the same form. On the whole torus (in PA-01's product approximation, PG-6) a Morse function has at least two saddles, and the Wilson-line potential has exactly two, nondegenerate, at the other two half-periods, at V = 0 exactly in the real spin structure. Also recorded: the Hessian eigenvalues 28.9 and 166.9 quoted for the jet vacuum are theta-coordinate values; the curvatures that set masses are those of G^-1 H in the kinetic metric (37.394 and 128.985). The atlas now reports two saddles; PA1-1 and every other result of PG-4 stand.", "mtft.matter.vacuum_atlas", "test_pg01_wilson_torus.py")
_e("CC-63", "correction", "EXACT", "active", "Supersedes TR-6 and seal PR-S1 by TR-8 and PR-S2, on the day of sealing and before any candidate: the strong-CP rule rejected theta = pi mirrors outright, but theta-bar = theta + arg det(M_u M_d), so a theta = pi point with arg det = pi passes (a real texture with negative determinant is that case); and theta-bar = pi is excluded by spectroscopy, not by the neutron EDM, which vanishes there. Also corrects PR-01's trial X12 from a_2 = 0 to a_2 even (supersingular at 2 includes 57 and 91) and TR-5's count of W_13's fixed points (four, over two classes). Found by independent review.", "mtft.matter.prereg", "test_pr01_prereg.py")
_e("CC-44", "correction", "EXACT", "active", "Caveats PB1-2, EPS1-2, HJ-2 and HJ-4: they tracked torus charge only, and the overall-U(1) audit forbids the leading amplitude they assumed.", "mtft.matter.yukawa_audit", "test_ya01_yukawa_audit.py")
_e("CC-43", "correction", "EXACT", "active", "Supersedes FS-4 and RT-1: a gamma-localised Higgs is A-type and cannot carry a tree-level Yukawa with A-type families; ratio 3 loses its coupling.", "mtft.matter.higgs_profile", "test_hp01_higgs_profile.py")
_e("CC-42", "correction", "EXACT", "active", "Retracts XQ-4: it paired the families with holomorphic messengers through the Bergman kernel, which the selection rule HJ-1 forbids at leading order.", "mtft.matter.jet_vertex", "test_hj01_jet_vertex.py")
_e("CC-41", "correction", "EXACT", "active", "Downgrades CP-12's numerical targets: they assumed unnormalised families; with nu = (1, sqrt 2, 1) the targets are rho = 0.568 (up), 0.684 (down), 0.408 (leptons).", "mtft.matter.overlaps", "test_xq01_overlaps.py")
_e("CC-40", "correction", "EXACT", "active", "Retracts CP-5: the texture is blind to zero flips of the profile, so the fits cannot place sectors in the coherent or polar phase.", "mtft.matter.condensate_phases", "test_cp01_condensate_phases.py")
_e("CC-39", "correction", "EXACT", "active", "Downgrades RT-1 and FS-4: vertex charges sum to zero, so up and down vertices differ in two charges (and in curve degree); the ratio near 3 is an estimate.", "mtft.matter.leptons", "test_lep01_leptons.py")
_e("CC-38", "correction", "EXACT", "active", "Supersedes PS-01's claim that Pati–Salam breaking needs the gamma direction: curve degrees suffice (FS-1).", "mtft.matter.flux_scan", "test_fs01_flux_scan.py")
_e("CC-36", "correction", "EXACT", "active", "Retracts AL1-4 and the tree-level origin of the SU(4) Yukawa relations in jet backgrounds.", "mtft.matter.yukawa_jets", "test_yk01_yukawa_jets.py")
_e("CC-37", "correction", "EXACT", "caveat", "Retires the one-family-per-cusp background for phenomenology; the single blown-up point is canonical.", "mtft.matter.ckm_cusps", "test_ck01_ckm_cusps.py", "CC-47: split assignments are not excluded by mixing alone in the canonical metric")

def entries(status=None, wave=None):
    return [e for e in E if (status is None or e["status"] == status) and (wave is None or e["wave"] == wave)]

def to_markdown():
    lines = ["# Matter programme ledger (generated by `mtft.matter.ledger`)", "", "| id | wave | class | status | statement | module | test |", "|---|---|---|---|---|---|---|"]
    for e in E:
        st = e["statement"] + (f" *({e['note']})*" if e["note"] else "")
        lines.append(f"| {e['id']} | {e['wave']} | {e['class']} | {e['status']} | {st} | `{e['module']}` | `{e['test']}` |")
    return "\n".join(lines) + "\n"

def check(tests_dir=None):
    tests_dir = Path(tests_dir) if tests_dir else Path(__file__).resolve().parents[3] / "tests"
    ids = [e["id"] for e in E]
    out = {"unique_ids": len(ids) == len(set(ids)), "modules_import": True, "tests_exist": True, "retractions_cite_correction": True}
    for e in E:
        try: import_module(e["module"])
        except Exception: out["modules_import"] = False
        if tests_dir.exists() and not (tests_dir / e["test"]).exists(): out["tests_exist"] = False
        if e["status"] == "retracted" and "CC-" not in e["note"]: out["retractions_cite_correction"] = False
    return out
